import{c as s,Q as a,j as t,m as e}from"./chunks/framework.DOi4mjdC.js";const o=JSON.parse('{"title":"概述","description":"","frontmatter":{},"headers":[{"level":1,"title":"概述","slug":"概述"}],"relativePath":"guide/跨代迁移兼容性指南/概述.md","filePath":"guide/跨代迁移兼容性指南/概述.md"}'),l={name:"guide/跨代迁移兼容性指南/概述.md"};function n(p,i,h,k,c,d){return a(),t("div",null,[...i[0]||(i[0]=[e(`<h1 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h1><p>Ascend C的核心设计目标之一是实现跨代兼容。然而，每一代芯片在微架构上都存在独特的硬件特性，因此无法保证所有接口仅通过重编译就能达成完全的跨代兼容。基于这一前提，本手册旨在为Ascend C算子开发者提供系统化指导，帮助将算子Kernel代码从当前芯片平滑移植到目标代际芯片上运行，实现高效、可控的迁移。</p><p>如<a href="./../编程指南/语言扩展层/SIMD-BuiltIn关键字.html">SIMD-BuiltIn关键字</a> 中所述，__NPU_ARCH__是Device侧AI Core代码中的一个预处理宏，用于标识AI处理器的架构版本。例如，Ascend 950PR/Ascend 950DT的__NPU_ARCH__为3510，而Atlas A3 训练系列产品/Atlas A3 推理系列产品的__NPU_ARCH__则为2201。因此，后续章节将以__NPU_ARCH__为主线，重点介绍相邻代际芯片间的平滑迁移方法。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>为保证兼容性，建议开发者在开发过程中尽量避免使用以下接口或编程方式，否则需自行保证兼容性：</p><ul><li>非 Ascend C 公开接口、结构体，例如 <code>impl</code> 目录下的接口、结构体等；</li><li>对芯片规格进行硬编码，例如：<div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">constexpr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MAX_UB_SIZE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 256</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1024</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 建议获取方式：</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, MAX_UB_SIZE);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span></code></pre></div></li><li>编译器内置 API（BuiltIn API），例如：<div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">copy_gm_to_ubuf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(input_1_local_UB, input_1, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div></li></ul></div><p>建议开发者采用以下实践：</p><ul><li>使用兼容的 API 接口。</li><li>若涉及特定领域的扩展特性，应在 Device 侧通过 <a href="./../编程指南/语言扩展层/SIMD-BuiltIn关键字.html"><code>__NPU_ARCH__</code> 编译宏</a>进行隔离，在 Host 侧通过 <code>SocVersion</code> 进行隔离。</li><li>使用 <code>&lt;&lt;&lt;&gt;&gt;&gt;</code> 直调或 <a href="./../编程指南/高级编程/高级特性/Aclnn算子工程化开发/Host侧Tiling实现/Tiling模板编程.html">Tiling 模板编程</a>。</li></ul><blockquote><p>💡 请参考<a href="https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/cannkit-ascend-kirin-compatibility" target="_blank" rel="noreferrer">昇腾到麒麟迁移指南</a>，了解如何将昇腾平台上开发的算子迁移到麒麟平台。</p></blockquote>`,7)])])}const _=s(l,[["render",n]]);export{o as __pageData,_ as default};
